t = Array[a, {2, 3, 4}];
TensorDimensions[TensorTranspose[t, {3, 1, 2}]] (* {4, 2, 3} *)
TensorSymmetry[{{0, 1}, {-1, 0}}] (* Antisymmetric[{1, 2}] *)

$Assumptions = {Element[a, Matrices[{3, 3}, Reals, Symmetric[{1, 2}]]], Element[v, Vectors[3]]};
TensorReduce[Transpose[a].v - a.v] (* 0 *)
TensorExpand[(a + Transpose[a]).v]

Symmetrize[{{1, 2}, {3, 4}}] (* {{1, 5/2}, {5/2, 4}} *)
eps = LeviCivitaTensor[3];
Cross[u, v] == TensorContract[TensorProduct[eps, u, v], {{2, 4}, {3, 5}}] // Simplify

m = {{1, 1}, {0, 0}};
DrazinInverse[m]
m.DrazinInverse[m].m == m

F = FourierMatrix[4];
UnitaryMatrixQ[F]
F.{1, 0, 0, 0} == Fourier[{1, 0, 0, 0}]

V = VandermondeMatrix[{1, 2, 3}];
Normal[V] (* {{1, 1, 1}, {1, 2, 4}, {1, 3, 9}} *)
coeffs = LinearSolve[V, {2, 5, 10}] (* interpolating polynomial coefficients *)

X = DesignMatrix[data, {x, x^2}, x];
y = data[[All, -1]];
beta = LeastSquares[X, y]
ridge = LinearSolve[Transpose[X].X + 0.1 IdentityMatrix[3], Transpose[X].y]

{b, m} = CoefficientArrays[{2 x + 3 y == 5, x - y == 1}, {x, y}];
LinearSolve[m, -b] (* {8/5, 3/5} *)
CoefficientArrays[x^2 + 2 x y + 3 y^2, {x, y}][[3]] // Normal

n = 10^4;
s = SparseArray[{{i_, i_} -> 4, {i_, j_} /; Abs[i - j] == 1 -> -1}, {n, n}];
x = LinearSolve[s, ConstantArray[1., n]];
s["Density"]
